// SI-generated: this file was generated by Claude Code (Anthropic, SI tool) and reviewed by the team.
// 觸覺（震動）與聲音回饋：不用看螢幕也知道「往哪修正、偏多遠、有沒有危險」。
//
// 編碼方式（團隊構想）：
//   偏離路線：1 下 = 往左修正，2 下 = 往右修正；偏越遠，間隔越短（頻率越高）
//   接近危險區：1 下長震
//   必須返回基地：SOS（··· ––– ···）
// 聲音：同樣的節奏用嗶聲播放，左右聲道表示路線在哪一側，音高隨偏離距離升高。
// 桌機沒有震動馬達，所以畫面上的震動圖示會同步閃爍，讓 demo 看得到。

const SOS = [80, 80, 80, 80, 80, 260, 260, 80, 260, 80, 260, 260, 80, 80, 80, 80, 80];
const sum = (a) => a.reduce((x, y) => x + y, 0);

export class Feedback {
  constructor(indicator) {
    this.sound = true;
    this.vibrate = true;
    this.indicator = indicator;
    this.ctx = null;
    this.nextAt = 0;
    this.lastKind = 'none';
  }

  unlockAudio() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (AC) this.ctx = new AC();
    }
    this.ctx?.resume?.();
  }

  /** 依目前狀態決定要不要發出下一組提示。state: {kind, xte, side} */
  update(now, state) {
    const { kind } = state;
    if (kind !== this.lastKind) this.nextAt = 0; // 狀態改變時立刻提示
    this.lastKind = kind;
    if (kind === 'none') {
      this.indicator.className = 'haptic idle';
      this.indicator.textContent = '📳 quiet — on route';
      return;
    }
    if (now < this.nextAt) return;

    let pattern, interval, freq, pan, text;
    if (kind === 'offroute') {
      const x = Math.min(Math.max(state.xte, 15), 60);
      interval = 1400 - ((x - 15) / 45) * 1150; // 15 m → 1.4 s，60 m → 0.25 s
      // side > 0：太空人在路線左側 → 路線在右邊 → 往右修正（2 下）
      const right = state.side > 0;
      pattern = right ? [70, 110, 70] : [70];
      freq = 480 + x * 10;
      pan = right ? 0.85 : -0.85;
      text = `📳 ${right ? '2 pulses → steer RIGHT' : '1 pulse → steer LEFT'} · ${state.xte.toFixed(0)} m off`;
    } else if (kind === 'hazard') {
      interval = 900;
      pattern = [380];
      freq = 200;
      pan = 0;
      text = '📳 long buzz → hazard close';
    } else {
      interval = 1800;
      pattern = SOS;
      freq = 880;
      pan = 0;
      text = '📳 SOS → return to base';
    }
    this.nextAt = now + interval + sum(pattern);
    if (this.vibrate && navigator.vibrate) navigator.vibrate(pattern);
    if (this.sound) this.beep(pattern, freq, pan);
    this.flash(pattern, text, kind);
  }

  beep(pattern, freq, pan) {
    const ctx = this.ctx;
    if (!ctx || ctx.state !== 'running') return;
    let t = ctx.currentTime + 0.02;
    pattern.forEach((ms, i) => {
      if (i % 2 === 0) {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const p = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
        osc.frequency.value = freq;
        osc.type = 'sine';
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.18, t + 0.01);
        gain.gain.setValueAtTime(0.18, t + ms / 1000 - 0.01);
        gain.gain.linearRampToValueAtTime(0, t + ms / 1000);
        if (p) { p.pan.value = pan; osc.connect(gain).connect(p).connect(ctx.destination); }
        else osc.connect(gain).connect(ctx.destination);
        osc.start(t);
        osc.stop(t + ms / 1000 + 0.02);
      }
      t += ms / 1000;
    });
  }

  flash(pattern, text, kind) {
    const el = this.indicator;
    el.textContent = text;
    let t = 0;
    pattern.forEach((ms, i) => {
      setTimeout(() => (el.className = `haptic ${kind} ${i % 2 === 0 ? 'on' : ''}`), t);
      t += ms;
    });
    setTimeout(() => (el.className = `haptic ${kind}`), t);
  }
}
